    'faq' => [
        ['q' => "Qui peut former mon ONG à l'IA en Côte d'Ivoire sans que l'équipe se déplace ?", 'r' => "Richard SALANON forme à distance, depuis Cotonou, avec une heure de décalage seulement : quand il est 9 heures à Abidjan, il est 10 heures à Cotonou. Les séances se tiennent en visioconférence sur vos documents de projet anonymisés, pour des équipes d'Abidjan comme des antennes régionales. Aucun déplacement n'est prévu en Côte d'Ivoire."],
        ['q' => "Une ONG peut-elle confier un rapport à un bailleur à ChatGPT ou à Claude ?", 'r' => "Elle peut confier le premier jet de la rédaction, à partir de fiches anonymisées et d'un tableau d'indicateurs déjà calculé, mais pas les chiffres ni la signature. Chaque nombre renvoie à la base du projet, chaque fait à une fiche d'activité, et une personne désignée relit et valide avant l'envoi. L'organisation répond seule de ce qu'elle remet au bailleur."],
        ['q' => "Que prévoit l'ordonnance de 2024 sur la société civile pour les rapports d'une ONG ?", 'r' => "L'ordonnance n° 2024-368 du 12 juin 2024, publiée au Journal officiel du 21 juin 2024, prévoit à son article 48 un rapport général d'activités de l'année écoulée à présenter au plus tard le 31 mars, et à son article 93 un compte financier annuel. Le texte applicable se vérifie au Journal officiel, et votre juriste tranche les cas particuliers."],
        ['q' => "La loi ivoirienne sur les données personnelles interdit-elle d'utiliser un assistant d'IA avec des données de bénéficiaires ?", 'r' => "La loi n° 2013-450 du 19 juin 2013 est citée par l'ARTCI, qui rappelle que les transferts hors de Côte d'Ivoire sont soumis à des restrictions et à des garanties. La formation apprend donc à ne pas envoyer de données nominatives à un assistant en ligne : extraits anonymisés, code à la place du nom, table d'identification conservée dans l'organisation. Pour les cas sensibles, consultez l'Autorité de protection ou votre juriste."],
        ['q' => "Le FDFP peut-il financer la formation d'une ONG ivoirienne ?", 'r' => "Rien n'est promis. La page du FDFP sur le plan de formation parle des entreprises qui paient régulièrement les deux taxes et ne mentionne pas les ONG ; demandez-lui par écrit si votre organisation peut déposer un plan. L'habilitation s'impose aux opérateurs privés, à l'exception des structures basées hors de Côte d'Ivoire : seul le Fonds dit si cette exception vaut pour un formateur établi au Bénin."],
        ['q' => "La formation couvre-t-elle KoboToolbox et la conception des formulaires de collecte ?", 'r' => "Non. La conception du formulaire reste l'affaire de l'équipe suivi-évaluation. La formation porte sur l'usage de l'assistant d'IA à partir de documents que l'équipe fournit, comme un export de tableur. Pour mémoire, selon la documentation de KoboToolbox, KoboCollect fonctionne sur Android et que les projets ne se partagent pas entre le serveur mondial et le serveur européen."],
        ['q' => "Comment se passe la formation si la connexion est mauvaise dans une antenne régionale ?", 'r' => "Les documents d'exercice sont téléchargés à l'avance, les consignes sont rédigées hors ligne puis collées en une fois, et les séances à distance durent 2 h 30. Une solution de repli est prévue en cas de coupure."],
        ['q' => "L'assistant peut-il traduire un questionnaire en baoulé ou en dioula ?", 'r' => "Il peut produire un texte, mais le résultat doit être relu par un locuteur avant tout usage, car les termes d'un questionnaire changent le sens des réponses. Le français et l'anglais sont mieux servis. Les consignes de traduction orale des enquêteurs restent celles de l'équipe de terrain."],
        ['q' => "Combien coûte la formation et comment la régler depuis la Côte d'Ivoire ?", 'r' => "Le prix est fixé sur devis, en FCFA, après le cadrage. Il dépend du nombre de participants, du format, de la préparation des exercices et des exigences du bailleur. Richard accepte le Mobile Money (MTN, Moov), la carte bancaire, PayPal, le virement et les espèces ; le mode se fixe au devis."],
        ['q' => "Reçoit-on une attestation, et un bailleur peut-il la demander ?", 'r' => "Oui, une attestation nominative de fin de formation par participant, avec le programme et les feuilles de présence, que beaucoup de bailleurs demandent pour justifier une dépense de renforcement des capacités. Ce n'est ni un diplôme ni une certification d'éditeur, et rien ne garantit qu'un bailleur l'accepte."],
        ['q' => "Faut-il acheter des abonnements avant la session ?", 'r' => "Non. Les versions gratuites de ChatGPT, Claude et Gemini suffisent pour apprendre la méthode. L'abonnement se décide après, sur ce qui a servi, et les formules et limites des éditeurs évoluent : la page officielle de chaque éditeur fait foi."],
